use crate::aap::caps::{http_client, state_rw};

struct Node;

const SEEN_VALUE: &str = "1";
const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

fn hex_digit(n: u8) -> char {
    match n {
        0..=9 => (b'0' + n) as char,
        _ => (b'A' + (n - 10)) as char,
    }
}

fn percent_encode(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for b in input.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(hex_digit(b >> 4));
                out.push(hex_digit(b & 0x0f));
            }
        }
    }
    out
}

/// `PublishedDigest` has no free-text field, so the enrichment query is built
/// from its date and the ids it considered.
fn input_text(published: &PublishedDigest) -> String {
    let mut s = published.date.clone();
    for id in &published.considered {
        s.push(' ');
        s.push_str(id);
    }
    s
}

/// Enrichment is advisory: its result never feeds the output, and a transport
/// failure is discarded rather than failing the run. A refused host still traps
/// at the boundary, as the capability contract requires.
fn enrich(published: &PublishedDigest) {
    let url = format!("{}{}", ENRICH_BASE, percent_encode(&input_text(published)));
    let _ = http_client::fetch(&url);
}

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        enrich(&published);

        let mut recorded: u32 = 0;
        for id in &published.considered {
            state_rw::put(id, SEEN_VALUE);
            recorded += 1;
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
```

